def minimum_beautiful_array_deletions(nums):
    kept=[];deleted=0
    for value in nums:
        if len(kept)%2==1 and kept[-1]==value:deleted+=1
        else:kept.append(value)
    if len(kept)%2:deleted+=1
    return deleted

